// --- Multi-sensor safe Function node with InfluxDB write ---

let payload = msg.payload;

if (Buffer.isBuffer(payload)) {
    payload = payload.toString('utf8');
}

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (err) {
        node.error("Invalid JSON payload", msg);
        return null;
    }
}

const device = payload.value;
if (!device) return null;

// Fields to ignore (non-metric)
const ignore = ["value", "snr", "pferror", "packetSize", "batt_status"];

// Valid measurement names: letters, numbers, underscores only
const validName = /^[a-zA-Z_][a-zA-Z0-9_]*$/;

// Valid device names: same rules
const validDevice = /^[a-zA-Z0-9_-]+$/;

if (!validDevice.test(device)) {
    node.warn(`Skipping bad device name: ${device}`);
    return null;
}

const messages = [];

for (const [key, val] of Object.entries(payload)) {
    if (ignore.includes(key)) continue;
    if (!validName.test(key)) {
        node.warn(`Skipping bad field name: ${key}`);
        continue;
    }

    const numVal = parseFloat(val);
    if (isNaN(numVal)) {
        node.warn(`Skipping non-numeric value for ${key}: ${val}`);
        continue;
    }

    // Message 1: to MQTT (existing behavior)
    // Message 2: to InfluxDB HTTP write
    messages.push([
        {
            topic: `LoRa_NodeRed/${device}/${key}`,
            payload: val,
            retain: true
        },
        {
            payload: `${key},device=${device} value=${numVal}`,
            headers: { "Content-Type": "text/plain" }
        }
    ]);
}

// Send all validated messages
for (const [mqttMsg, influxMsg] of messages) {
    node.send([mqttMsg, influxMsg]);
}

return null;

